    input  areset,
    input  predict_valid,
    input  predict_taken,
    input  train_mispredicted,
    input  train_taken,
    input  [31:0] train_history,
    output [31:0] predict_history
    );

    reg [31:0] history;
    reg [31:0] history_next;
    reg [31:0] predict_history_reg;
    wire [31:0] history_rollback;
    wire [31:0] history_next_new;

    // Perform the pipeline flush on a mispredicted branch, with
    // predict_valid=1 indicating that a branch is currently being
    // predicted. This should have the effect of rolling back the state
    // one cycle, because the register update will happen the next
    // cycle, and the prediction for the same branch will also happen
    // on the next cycle.
    assign history_rollback = {history[30:0], predict_taken};

    // Next stage history: shift in the prediction from the LSB side.
    assign history_next_new = {history[29:0], predict_taken};

    // The register update.
    always @(posedge clk) begin
        if (areset)
            history <= 32'h0;
        else
            history <= history_next;
    end

    // The prediction history register.
    always @(posedge clk) begin
        predict_history_reg <= history;
    end

    // The actual branch history register update.
    always @(*) begin
        if (train_mispredicted)
            history_next = train_history;
        else if (predict_valid)
            history_next = history_next_new;
        else
            history_next = history_rollback;
    end

    assign predict_history = predict_history_reg;

endmodule

